    TwistExpander_Pollux_Arx::KEY_A_D_E(PARAMS_SEED);

    TwistSquash::SquashKeyA(POLLUX_KEY_A_D_IceLaneA, POLLUX_KEY_A_D_IceLaneB, POLLUX_KEY_A_D_IceLaneC, POLLUX_KEY_A_D_IceLaneD, &(pWorkSpace->mKeyBoxA[3U][0]));

